    if(j.encounters) h+='<p class="loc-desc"><strong class="loc-lbl">Encounters:</strong></p><div class="mod-list">'+j.encounters.split('\n').filter(Boolean).map(x=>'<div class="sb-ability">⚔ '+fmtText(x)+'</div>').join('')+'</div>';
